import React, { useEffect, useState } from "react";
import axios from "axios";
import { Html5Qrcode } from "html5-qrcode";
import { useNavigate } from "react-router-dom";

function QRScanner() {

const [user,setUser] = useState(null);
const [message,setMessage] = useState("");

const navigate = useNavigate();

useEffect(()=>{

const admin = localStorage.getItem("admin");

if(!admin){
alert("Please login as admin");
navigate("/admin-login");
return;
}

const scanner = new Html5Qrcode("reader");

async function startScanner(){

try{

const cameras = await Html5Qrcode.getCameras();

if(cameras && cameras.length){

await scanner.start(
cameras[0].id,
{
fps:10,
qrbox:250
},
(decodedText)=>{

console.log("QR:",decodedText);

verifyUser(decodedText);

},
(error)=>{
// ignore scan errors
}
);

}

}catch(err){

console.log("Camera error:",err);

}

}

startScanner();

return ()=>{

scanner.stop().catch(()=>{});

};

},[navigate]);

/* VERIFY USER */

const verifyUser = async(id)=>{

try{

const res = await axios.get(
`http://localhost:5000/verify-user/${id}`
);

if(res.data.success){

setUser(res.data.user);

setMessage("✅ VERIFIED");

await axios.put(
`http://localhost:5000/mark-attendance/${id}`
);

}else{

setUser(null);

setMessage("❌ NOT REGISTERED");

}

}catch(err){

console.log(err);

setMessage("⚠️ SERVER ERROR");

}

};

return(

<div style={{padding:"20px"}}>

<h2>Admin QR Scanner</h2>

<div id="reader" style={{width:"350px"}}></div>

<h3>{message}</h3>

{user && (

<div style={{marginTop:"15px"}}>

<p>Name: {user.name}</p>
<p>College: {user.college_name}</p>
<p>Phone: {user.phone}</p>
<p>Event: {user.event_id}</p>

</div>

)}

</div>

);

}

export default QRScanner;
